package com.example.crm.customer;
import org.junit.jupiter.api.*; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.setup.MockMvcBuilders.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.util.*;
class CustomerControllerTest { MockMvc mvc; CustomerService service; @BeforeEach void set(){service=mock(CustomerService.class);mvc=standaloneSetup(new CustomerController(service)).build();} @Test void listsCustomers(){when(service.findAll()).thenReturn(List.of(new CustomerDto(UUID.randomUUID(),"Acme","a@b.test",null,null))); try{mvc.perform(get("/api/customers")).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("Acme"));}catch(Exception e){throw new RuntimeException(e);}} }
